//! Runtime support functions implementing jq value semantics.
//!
//! Code generated by `jq!` calls into these rather than re-implementing jq's
//! type coercion and ordering rules inline at every call site.

use std::cell::Cell;
use std::cmp::Ordering;

use serde_json::{Map, Number, Value};

use crate::error::{JResult, JqError};

/// Caps structural recursion in comparison/equality/containment/object-
/// merge, the same fix in spirit as jq's own `MAX_CMP_DEPTH`/
/// `MAX_EQUAL_DEPTH`/`MAX_CONTAINS_DEPTH`/`MAX_OBJECT_MERGE_DEPTH` (`src/
/// jv_aux.c`/`src/jv.c`, all four 10000) for CVE-2026-33947/-40612/-43896:
/// a deliberately deep nested array/object used to stack-overflow jq's own
/// recursive C implementation.
///
/// This is *not* jq's own 10000, though: jqc-core's recursion here has
/// meaningfully heavier per-level stack usage (`Value` is a full
/// `serde_json::Value`, cloned/dropped recursively, versus jq's
/// reference-counted `jv`), empirically overflowing a default ~8MiB thread
/// stack well short of depth 10000 -- object-merge (`*`) was the first to
/// go, between depth 700 and 1000. 500 is comfortably under every
/// empirically-found threshold (contains_value: ~1800-2000; cmp_values,
/// used by sort/unique: ~1000-2000; deep_merge: ~700-1000), so this trades
/// jq's exact depth tolerance for a cap jqc can actually honor without
/// crashing -- a real, documented divergence from real jq (which still
/// succeeds between 500 and 10000), not merely a cosmetic one, but a
/// clean, catchable error is still the correct trade against a hard
/// process-ending stack overflow.
pub(crate) const MAX_STRUCTURAL_DEPTH: u32 = 500;

pub fn type_name(v: &Value) -> &'static str {
    match v {
        Value::Null => "null",
        Value::Bool(_) => "boolean",
        Value::Number(_) => "number",
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

/// jq truthiness: everything is truthy except `false` and `null`.
pub fn truthy(v: &Value) -> bool {
    !matches!(v, Value::Null | Value::Bool(false))
}

fn num_f64(n: &Number) -> f64 {
    n.as_f64().unwrap_or(f64::NAN)
}

/// jq prints whole-number results without a decimal point (`6`, not
/// `6.0`); `serde_json::Number::from_f64` always keeps float formatting, so
/// every number produced by generated code is built through this instead.
pub fn number_from_f64(f: f64) -> Number {
    if f.is_finite() && f == f.trunc() && f.abs() < 1e18 {
        Number::from(f as i64)
    } else {
        Number::from_f64(f).unwrap_or_else(|| Number::from(0))
    }
}

/// jq's total ordering over JSON values: null < false < true < numbers <
/// strings < arrays < objects. `too_deep` is a side-channel (mirroring jq's
/// own `sort_cmp_state.too_deep` in `src/jv_aux.c`, needed for the same
/// reason: a `[T]::sort_by`-style comparator can't itself return a
/// `Result`) set once `depth` exceeds [`MAX_STRUCTURAL_DEPTH`], after which
/// every further call just returns `Equal` without recursing -- the caller
/// checks it once after the whole comparison/sort is done.
fn cmp_values_at(lhs: &Value, rhs: &Value, depth: u32, too_deep: &Cell<bool>) -> Ordering {
    fn rank(v: &Value) -> u8 {
        match v {
            Value::Null => 0,
            Value::Bool(false) => 1,
            Value::Bool(true) => 2,
            Value::Number(_) => 3,
            Value::String(_) => 4,
            Value::Array(_) => 5,
            Value::Object(_) => 6,
        }
    }
    if depth > MAX_STRUCTURAL_DEPTH {
        too_deep.set(true);
        return Ordering::Equal;
    }
    match (lhs, rhs) {
        (Value::Null, Value::Null) => Ordering::Equal,
        (Value::Bool(x), Value::Bool(y)) => x.cmp(y),
        (Value::Number(x), Value::Number(y)) => num_f64(x)
            .partial_cmp(&num_f64(y))
            .unwrap_or(Ordering::Equal),
        (Value::String(x), Value::String(y)) => x.cmp(y),
        (Value::Array(x), Value::Array(y)) => {
            for (xi, yi) in x.iter().zip(y.iter()) {
                let o = cmp_values_at(xi, yi, depth + 1, too_deep);
                if o != Ordering::Equal {
                    return o;
                }
            }
            x.len().cmp(&y.len())
        }
        (Value::Object(x), Value::Object(y)) => {
            let mut xk: Vec<&String> = x.keys().collect();
            let mut yk: Vec<&String> = y.keys().collect();
            xk.sort();
            yk.sort();
            if xk != yk {
                return xk.cmp(&yk);
            }
            for k in xk {
                let o = cmp_values_at(&x[k], &y[k], depth + 1, too_deep);
                if o != Ordering::Equal {
                    return o;
                }
            }
            Ordering::Equal
        }
        _ => rank(lhs).cmp(&rank(rhs)),
    }
}

pub fn cmp_values(lhs: &Value, rhs: &Value) -> Ordering {
    cmp_values_at(lhs, rhs, 0, &Cell::new(false))
}

pub fn eq_values(lhs: &Value, rhs: &Value) -> bool {
    cmp_values(lhs, rhs) == Ordering::Equal
}

/// As [`cmp_values`], but erroring (matching real jq's own
/// `MAX_CMP_DEPTH`-triggered "Comparison too deep") instead of silently
/// returning a wrong ordering once [`MAX_STRUCTURAL_DEPTH`] is exceeded --
/// used by the user-facing `<`/`<=`/`>`/`>=` operators.
pub fn try_cmp_values(lhs: &Value, rhs: &Value) -> JResult<Ordering> {
    let too_deep = Cell::new(false);
    let ord = cmp_values_at(lhs, rhs, 0, &too_deep);
    if too_deep.get() {
        Err(JqError::msg("Comparison too deep"))
    } else {
        Ok(ord)
    }
}

/// As [`eq_values`], but erroring (matching real jq's own
/// `MAX_EQUAL_DEPTH`-triggered "Equality check too deep") instead of
/// silently returning a wrong answer once [`MAX_STRUCTURAL_DEPTH`] is
/// exceeded -- used by the user-facing `==`/`!=` operators.
pub fn try_eq_values(lhs: &Value, rhs: &Value) -> JResult<bool> {
    let too_deep = Cell::new(false);
    let ord = cmp_values_at(lhs, rhs, 0, &too_deep);
    if too_deep.get() {
        Err(JqError::msg("Equality check too deep"))
    } else {
        Ok(ord == Ordering::Equal)
    }
}

fn type_err(op: &str, lhs: &Value, rhs: &Value) -> JqError {
    JqError::msg(format!(
        "{} ({}) and {} ({}) cannot be {}",
        type_name(lhs),
        lhs,
        type_name(rhs),
        rhs,
        op
    ))
}

/// jq's `+` operator: null-absorbing, numeric add, string/array
/// concatenation, shallow object merge (right-biased).
pub fn add_values(lhs: Value, rhs: Value) -> JResult<Value> {
    Ok(match (lhs, rhs) {
        (Value::Null, x) | (x, Value::Null) => x,
        (Value::Number(x), Value::Number(y)) => {
            Value::Number(number_from_f64(num_f64(&x) + num_f64(&y)))
        }
        (Value::String(x), Value::String(y)) => Value::String(x + &y),
        (Value::Array(mut x), Value::Array(y)) => {
            x.extend(y);
            Value::Array(x)
        }
        (Value::Object(mut x), Value::Object(y)) => {
            for (k, v) in y {
                x.insert(k, v);
            }
            Value::Object(x)
        }
        (lhs, rhs) => return Err(type_err("added", &lhs, &rhs)),
    })
}

pub fn sub_values(lhs: Value, rhs: Value) -> JResult<Value> {
    Ok(match (&lhs, &rhs) {
        (Value::Number(x), Value::Number(y)) => {
            Value::Number(number_from_f64(num_f64(x) - num_f64(y)))
        }
        (Value::Array(x), Value::Array(y)) => {
            Value::Array(x.iter().filter(|e| !y.contains(e)).cloned().collect())
        }
        _ => return Err(type_err("subtracted", &lhs, &rhs)),
    })
}

/// Real jq's own string-repeat cap, `INT_MAX - sizeof(jvp_string) / 2`
/// bytes (`src/jv.c`'s `jv_string_repeat`); the exact few bytes of slack
/// don't matter here (this only exists to reject something ~2GB+, not to
/// pin the precise boundary), so this just uses `i32::MAX` itself.
const MAX_STRING_REPEAT_BYTES: i64 = i32::MAX as i64;

pub fn mul_values(lhs: Value, rhs: Value) -> JResult<Value> {
    Ok(match (&lhs, &rhs) {
        (Value::Number(x), Value::Number(y)) => {
            Value::Number(number_from_f64(num_f64(x) * num_f64(y)))
        }
        (Value::String(s), Value::Number(n)) | (Value::Number(n), Value::String(s)) => {
            let n = num_f64(n);
            // Real jq truncates (not floors) the count and treats negative
            // (or NaN) as "no repeat" (null), *not* an error: `.[] * "abc"`
            // in jq's own C test suite confirms `0 <= n < 1` gives `""`,
            // not `null` -- the previous `n <= 0.0` check here wrongly
            // nulled out `n == 0.0` too.
            if n < 0.0 || n.is_nan() {
                Value::Null
            } else {
                let count = if n > i32::MAX as f64 {
                    i32::MAX as i64
                } else {
                    n as i64
                };
                match (s.len() as i64).checked_mul(count) {
                    Some(len) if len < MAX_STRING_REPEAT_BYTES => {
                        Value::String(s.repeat(count as usize))
                    }
                    _ => return Err(JqError::msg("Repeat string result too long")),
                }
            }
        }
        (Value::Object(_), Value::Object(_)) => deep_merge(lhs, rhs)?,
        _ => return Err(type_err("multiplied", &lhs, &rhs)),
    })
}

fn deep_merge(lhs: Value, rhs: Value) -> JResult<Value> {
    deep_merge_at(lhs, rhs, 0)
}

fn deep_merge_at(lhs: Value, rhs: Value, depth: u32) -> JResult<Value> {
    if depth > MAX_STRUCTURAL_DEPTH {
        return Err(JqError::msg("Object merge too deep"));
    }
    Ok(match (lhs, rhs) {
        (Value::Object(mut x), Value::Object(y)) => {
            for (k, v) in y {
                let merged = match x.remove(&k) {
                    Some(existing) => deep_merge_at(existing, v, depth + 1)?,
                    None => v,
                };
                x.insert(k, merged);
            }
            Value::Object(x)
        }
        (_, rhs) => rhs,
    })
}

pub fn div_values(lhs: Value, rhs: Value) -> JResult<Value> {
    Ok(match (&lhs, &rhs) {
        (Value::Number(x), Value::Number(y)) => {
            let yv = num_f64(y);
            if yv == 0.0 {
                return Err(JqError::msg(format!(
                    "{lhs} and {rhs} cannot be divided because the divisor is zero"
                )));
            }
            Value::Number(number_from_f64(num_f64(x) / yv))
        }
        (Value::String(x), Value::String(y)) => Value::Array(
            x.split(y.as_str())
                .map(|s| Value::String(s.to_string()))
                .collect(),
        ),
        _ => return Err(type_err("divided", &lhs, &rhs)),
    })
}

pub fn mod_values(lhs: Value, rhs: Value) -> JResult<Value> {
    Ok(match (&lhs, &rhs) {
        (Value::Number(x), Value::Number(y)) => {
            let yi = num_f64(y).trunc() as i64;
            if yi == 0 {
                return Err(JqError::msg(format!(
                    "{lhs} and {rhs} cannot be divided because the divisor is zero"
                )));
            }
            let xi = num_f64(x).trunc() as i64;
            Value::Number(Number::from(xi % yi))
        }
        _ => return Err(type_err("divided", &lhs, &rhs)),
    })
}

pub fn neg_value(v: Value) -> JResult<Value> {
    match v {
        Value::Number(n) => Ok(Value::Number(number_from_f64(-num_f64(&n)))),
        other => Err(JqError::msg(format!(
            "{} ({}) cannot be negated",
            type_name(&other),
            other
        ))),
    }
}

fn to_i64_index(n: &Number, len: usize) -> i64 {
    let f = num_f64(n).floor();
    let i = f as i64;
    if i < 0 {
        i + len as i64
    } else {
        i
    }
}

/// `.foo` field access. Indexing `null` yields `null`; indexing anything
/// other than an object or `null` with a string key is an error.
pub fn index_field(v: &Value, name: &str) -> JResult<Value> {
    match v {
        Value::Null => Ok(Value::Null),
        Value::Object(m) => Ok(m.get(name).cloned().unwrap_or(Value::Null)),
        other => Err(JqError::msg(format!(
            "Cannot index {} with \"{}\"",
            type_name(other),
            name
        ))),
    }
}

/// Generic `.[key]` indexing, where `key` may be a string (object field) or
/// number (array element, negative counts from the end).
pub fn index_value(v: &Value, key: &Value) -> JResult<Value> {
    match (v, key) {
        (Value::Null, Value::String(_) | Value::Number(_)) => Ok(Value::Null),
        (Value::Object(m), Value::String(s)) => Ok(m.get(s).cloned().unwrap_or(Value::Null)),
        (Value::Array(a), Value::Number(n)) => {
            let idx = to_i64_index(n, a.len());
            if idx < 0 {
                Ok(Value::Null)
            } else {
                Ok(a.get(idx as usize).cloned().unwrap_or(Value::Null))
            }
        }
        (other, key) => Err(JqError::msg(format!(
            "Cannot index {} with {}",
            type_name(other),
            type_name(key)
        ))),
    }
}

fn clamp_range(from: Option<i64>, to: Option<i64>, len: usize) -> (usize, usize) {
    let len_i = len as i64;
    let norm = |i: i64| -> i64 {
        if i < 0 {
            (i + len_i).max(0)
        } else {
            i.min(len_i)
        }
    };
    let f = norm(from.unwrap_or(0));
    let t = norm(to.unwrap_or(len_i)).max(f);
    (f as usize, t as usize)
}

pub fn slice_value(v: &Value, from: Option<i64>, to: Option<i64>) -> JResult<Value> {
    match v {
        Value::Null => Ok(Value::Null),
        Value::Array(a) => {
            let (f, t) = clamp_range(from, to, a.len());
            Ok(Value::Array(a[f..t].to_vec()))
        }
        Value::String(s) => {
            let chars: Vec<char> = s.chars().collect();
            let (f, t) = clamp_range(from, to, chars.len());
            Ok(Value::String(chars[f..t].iter().collect()))
        }
        other => Err(JqError::msg(format!(
            "Cannot index {} with object",
            type_name(other)
        ))),
    }
}

pub fn iterate(v: &Value) -> JResult<Vec<Value>> {
    match v {
        Value::Array(a) => Ok(a.clone()),
        Value::Object(m) => Ok(m.values().cloned().collect()),
        other => Err(JqError::msg(format!(
            "Cannot iterate over {} ({})",
            type_name(other),
            other
        ))),
    }
}

pub fn length_of(v: &Value) -> JResult<Value> {
    Ok(match v {
        Value::Null => Value::Number(Number::from(0)),
        Value::Bool(_) => {
            return Err(JqError::msg(format!(
                "{} ({}) has no length",
                type_name(v),
                v
            )))
        }
        Value::Number(n) => Value::Number(number_from_f64(num_f64(n).abs())),
        Value::String(s) => Value::Number(Number::from(s.chars().count() as i64)),
        Value::Array(a) => Value::Number(Number::from(a.len() as i64)),
        Value::Object(m) => Value::Number(Number::from(m.len() as i64)),
    })
}

pub fn keys_of(v: &Value, sorted: bool) -> JResult<Value> {
    match v {
        Value::Object(m) => {
            let mut ks: Vec<String> = m.keys().cloned().collect();
            if sorted {
                ks.sort();
            }
            Ok(Value::Array(ks.into_iter().map(Value::String).collect()))
        }
        Value::Array(a) => Ok(Value::Array(
            (0..a.len() as i64)
                .map(|i| Value::Number(Number::from(i)))
                .collect(),
        )),
        other => Err(JqError::msg(format!(
            "{} ({}) has no keys",
            type_name(other),
            other
        ))),
    }
}

/// Real jq's `jv_has` (`src/jv_aux.c`) special-cases a `null` container:
/// always `false`, regardless of the key's own type -- confirmed via
/// `jqc`'s own fuzz_scripts suite, which found `null | has(...)` (via
/// `in`, which delegates to `has`) erroring here instead.
pub fn has_key(v: &Value, key: &Value) -> JResult<Value> {
    Ok(Value::Bool(match (v, key) {
        (Value::Null, _) => false,
        (Value::Object(m), Value::String(s)) => m.contains_key(s),
        (Value::Array(a), Value::Number(n)) => {
            let i = num_f64(n) as i64;
            i >= 0 && (i as usize) < a.len()
        }
        (other, key) => {
            return Err(JqError::msg(format!(
                "Cannot check whether {} has a key of type {}",
                type_name(other),
                type_name(key)
            )))
        }
    }))
}

pub fn add_all(items: &[Value]) -> JResult<Value> {
    let mut acc = Value::Null;
    for item in items {
        acc = add_values(acc, item.clone())?;
    }
    Ok(acc)
}

/// `too_deep.get()` after `body` runs decides between `Ok(value())` and the
/// given too-deep error message -- the shared tail of every sort/group/
/// unique/min/max helper below, each of which drives one or more
/// [`cmp_values_at`] calls through a single [`Cell`] spanning the *whole*
/// operation (mirroring jq's own per-sort `sort_cmp_state`, needed for the
/// same reason: `[T]::sort_by`/`min_by`/`max_by`/`dedup_by`'s comparator
/// closures can't themselves return a `Result`).
fn finish_structural<T>(too_deep: &Cell<bool>, msg: &str, value: T) -> JResult<T> {
    if too_deep.get() {
        Err(JqError::msg(msg.to_string()))
    } else {
        Ok(value)
    }
}

pub fn sort_values(mut items: Vec<Value>) -> JResult<Vec<Value>> {
    let too_deep = Cell::new(false);
    items.sort_by(|a, b| cmp_values_at(a, b, 0, &too_deep));
    finish_structural(&too_deep, "Comparison too deep", items)
}

/// Sort `items` by parallel `keys` (already computed per-item), stable.
pub fn sort_by_keys(items: Vec<Value>, keys: Vec<Value>) -> JResult<Vec<Value>> {
    let too_deep = Cell::new(false);
    let mut paired: Vec<(Value, Value)> = keys.into_iter().zip(items).collect();
    paired.sort_by(|a, b| cmp_values_at(&a.0, &b.0, 0, &too_deep));
    finish_structural(
        &too_deep,
        "Comparison too deep",
        paired.into_iter().map(|(_, v)| v).collect(),
    )
}

pub fn group_by_keys(items: Vec<Value>, keys: Vec<Value>) -> JResult<Vec<Value>> {
    let too_deep = Cell::new(false);
    let mut paired: Vec<(Value, Value)> = keys.into_iter().zip(items).collect();
    paired.sort_by(|a, b| cmp_values_at(&a.0, &b.0, 0, &too_deep));
    let mut groups: Vec<Value> = Vec::new();
    let mut cur_key: Option<Value> = None;
    let mut cur_group: Vec<Value> = Vec::new();
    for (k, v) in paired {
        match &cur_key {
            Some(ck) if cmp_values_at(ck, &k, 0, &too_deep) == Ordering::Equal => cur_group.push(v),
            _ => {
                if !cur_group.is_empty() {
                    groups.push(Value::Array(std::mem::take(&mut cur_group)));
                }
                cur_key = Some(k);
                cur_group.push(v);
            }
        }
    }
    if !cur_group.is_empty() {
        groups.push(Value::Array(cur_group));
    }
    finish_structural(&too_deep, "Comparison too deep", groups)
}

pub fn unique_values(items: Vec<Value>) -> JResult<Vec<Value>> {
    let too_deep = Cell::new(false);
    let mut items = items;
    items.sort_by(|a, b| cmp_values_at(a, b, 0, &too_deep));
    items.dedup_by(|a, b| cmp_values_at(a, b, 0, &too_deep) == Ordering::Equal);
    finish_structural(&too_deep, "Equality check too deep", items)
}

pub fn unique_by_keys(items: Vec<Value>, keys: Vec<Value>) -> JResult<Vec<Value>> {
    Ok(group_by_keys(items, keys)?
        .into_iter()
        .filter_map(|g| match g {
            Value::Array(mut a) if !a.is_empty() => Some(a.remove(0)),
            _ => None,
        })
        .collect())
}

pub fn min_by_keys(items: Vec<Value>, keys: Vec<Value>) -> JResult<Value> {
    let too_deep = Cell::new(false);
    let result = keys
        .into_iter()
        .zip(items)
        .min_by(|a, b| cmp_values_at(&a.0, &b.0, 0, &too_deep))
        .map(|(_, v)| v)
        .unwrap_or(Value::Null);
    finish_structural(&too_deep, "Comparison too deep", result)
}

pub fn max_by_keys(items: Vec<Value>, keys: Vec<Value>) -> JResult<Value> {
    let too_deep = Cell::new(false);
    let result = keys
        .into_iter()
        .zip(items)
        .max_by(|a, b| cmp_values_at(&a.0, &b.0, 0, &too_deep))
        .map(|(_, v)| v)
        .unwrap_or(Value::Null);
    finish_structural(&too_deep, "Comparison too deep", result)
}

pub fn min_values(items: &[Value]) -> JResult<Value> {
    let too_deep = Cell::new(false);
    let result = items
        .iter()
        .cloned()
        .min_by(|a, b| cmp_values_at(a, b, 0, &too_deep))
        .unwrap_or(Value::Null);
    finish_structural(&too_deep, "Comparison too deep", result)
}

pub fn max_values(items: &[Value]) -> JResult<Value> {
    let too_deep = Cell::new(false);
    let result = items
        .iter()
        .cloned()
        .max_by(|a, b| cmp_values_at(a, b, 0, &too_deep))
        .unwrap_or(Value::Null);
    finish_structural(&too_deep, "Comparison too deep", result)
}

/// Matches real jq (1.8): `reverse` only accepts arrays and `null`, even
/// though strings are "reversible" -- jq implements it as `[.[]] | ...`,
/// which errors on indexing a string by number.
pub fn reverse_value(v: &Value) -> JResult<Value> {
    match v {
        Value::Array(a) => {
            let mut a = a.clone();
            a.reverse();
            Ok(Value::Array(a))
        }
        Value::Null => Ok(Value::Array(vec![])),
        other => Err(JqError::msg(format!(
            "Cannot index {} with number",
            type_name(other)
        ))),
    }
}

pub fn range_values(from: f64, to: f64, step: f64) -> Vec<Value> {
    let mut out = Vec::new();
    if step > 0.0 {
        let mut x = from;
        while x < to {
            out.push(Value::Number(number_from_f64(x)));
            x += step;
        }
    } else if step < 0.0 {
        let mut x = from;
        while x > to {
            out.push(Value::Number(number_from_f64(x)));
            x += step;
        }
    }
    out
}

pub fn value_to_f64(v: &Value) -> JResult<f64> {
    match v {
        Value::Number(n) => Ok(num_f64(n)),
        other => Err(JqError::msg(format!(
            "{} is not a number",
            type_name(other)
        ))),
    }
}

pub fn value_to_i64(v: &Value) -> JResult<i64> {
    value_to_f64(v).map(|f| f as i64)
}

pub fn as_array(v: &Value) -> JResult<&Vec<Value>> {
    match v {
        Value::Array(a) => Ok(a),
        other => Err(JqError::msg(format!(
            "{} is not an array",
            type_name(other)
        ))),
    }
}

pub fn as_str(v: &Value) -> JResult<&str> {
    match v {
        Value::String(s) => Ok(s),
        other => Err(JqError::msg(format!(
            "{} is not a string",
            type_name(other)
        ))),
    }
}

/// Real jq's `f_contains` (`src/builtin.c`) checks this -- same
/// `jv_kind` -- only once, at the top level, before ever recursing; a
/// *nested* kind mismatch (an array element of the wrong kind, say) isn't
/// an error, just a reason that one element doesn't match (`contains_at`
/// below already gets that right structurally, via `eq_values` returning
/// `false` for mismatched kinds rather than erroring).
pub fn contains_value(lhs: &Value, rhs: &Value) -> JResult<bool> {
    // jq's `jv_kind` (what `f_contains` actually compares) distinguishes
    // `true`/`false` as separate kinds, unlike `type_name` (both report
    // "boolean") -- `true | contains(false)` really does error in real
    // jq, confirmed directly, not just a same-`type_name` same-type case.
    fn kind(v: &Value) -> u8 {
        match v {
            Value::Null => 0,
            Value::Bool(false) => 1,
            Value::Bool(true) => 2,
            Value::Number(_) => 3,
            Value::String(_) => 4,
            Value::Array(_) => 5,
            Value::Object(_) => 6,
        }
    }
    if kind(lhs) != kind(rhs) {
        return Err(JqError::msg(format!(
            "{} ({}) and {} ({}) cannot have their containment checked",
            type_name(lhs),
            lhs,
            type_name(rhs),
            rhs
        )));
    }
    contains_at(lhs, rhs, 0)
}

fn contains_at(lhs: &Value, rhs: &Value, depth: u32) -> JResult<bool> {
    if depth > MAX_STRUCTURAL_DEPTH {
        return Err(JqError::msg("Containment check too deep"));
    }
    Ok(match (lhs, rhs) {
        (Value::Object(x), Value::Object(y)) => {
            for (k, yv) in y {
                match x.get(k) {
                    Some(xv) if contains_at(xv, yv, depth + 1)? => {}
                    _ => return Ok(false),
                }
            }
            true
        }
        (Value::Array(x), Value::Array(y)) => {
            for yv in y {
                let mut found = false;
                for xv in x {
                    if contains_at(xv, yv, depth + 1)? {
                        found = true;
                        break;
                    }
                }
                if !found {
                    return Ok(false);
                }
            }
            true
        }
        (Value::String(x), Value::String(y)) => x.contains(y.as_str()),
        (x, y) => eq_values(x, y),
    })
}

pub fn startswith(v: &Value, prefix: &Value) -> JResult<Value> {
    Ok(Value::Bool(as_str(v)?.starts_with(as_str(prefix)?)))
}

pub fn endswith(v: &Value, suffix: &Value) -> JResult<Value> {
    Ok(Value::Bool(as_str(v)?.ends_with(as_str(suffix)?)))
}

/// Real jq defines this as `if startswith($left) then .[$left|length:] end`
/// (`src/builtin.jq`): `startswith` requires both operands to be strings
/// and errors otherwise, so `ltrimstr`/`rtrimstr` do too -- confirmed via
/// `jqc`'s own fuzz_inputs suite, which found this returning `.` unchanged
/// instead of erroring for a non-string input/prefix.
pub fn ltrimstr(v: &Value, prefix: &Value) -> JResult<Value> {
    let s = as_str(v)?;
    let p = as_str(prefix)?;
    Ok(Value::String(s.strip_prefix(p).unwrap_or(s).to_string()))
}

pub fn rtrimstr(v: &Value, suffix: &Value) -> JResult<Value> {
    let s = as_str(v)?;
    let p = as_str(suffix)?;
    Ok(Value::String(s.strip_suffix(p).unwrap_or(s).to_string()))
}

/// Real jq defines this as (`src/builtin.jq`):
/// ```jq
/// reduce .[] as $i (null;
///     (if .==null then "" else .+$x end) +
///     ($i | if type=="boolean" or type=="number" then tostring else .//"" end)
/// ) // ""
/// ```
/// -- reimplemented structurally (not just "stringify and concatenate")
/// because its exact edge cases only fall out of that structure: `.[]`
/// isn't specifically an array, so `join` works on an object's values
/// too (confirmed via `jqc`'s own fuzz_inputs suite: `{} | join(...)`
/// succeeds with `""`, same as `[] | join(...)`, since both iterate zero
/// elements); the separator is combined with `+` (not required to be a
/// string outright), so jq's own null-absorption applies -- a `null`
/// separator is silently absorbed rather than erroring, *and* is never
/// even evaluated at all between fewer than two elements (confirmed:
/// `{"a":null,"c":null} | join(null)` succeeds with `""`, since `+`
/// absorbs the null separator, while `[1,2] | join(null)` would still
/// error, since `+`ing a null separator onto an all-ready-numeric-looking
/// *string* accumulator is still a string+null, which is absorbed too --
/// only a non-string-non-null separator ever errors, and only once
/// there's a second element for it to actually appear between).
pub fn join_strings(v: &Value, sep: &Value) -> JResult<Value> {
    let items = iterate(v)?;
    let mut acc: Option<Value> = None;
    for item in &items {
        let with_sep = match acc {
            None => Value::String(String::new()),
            Some(a) => add_values(a, sep.clone())?,
        };
        let elem = match item {
            Value::Bool(_) | Value::Number(_) => Value::String(value_to_display_string(item)),
            other if truthy(other) => other.clone(),
            _ => Value::String(String::new()),
        };
        acc = Some(add_values(with_sep, elem)?);
    }
    match acc {
        Some(a) if truthy(&a) => Ok(a),
        _ => Ok(Value::String(String::new())),
    }
}

pub fn split_string(v: &Value, sep: &Value) -> JResult<Value> {
    let s = as_str(v)?;
    let sep = as_str(sep)?;
    if sep.is_empty() {
        return Err(JqError::msg("split input and separator must not be empty"));
    }
    Ok(Value::Array(
        s.split(sep).map(|p| Value::String(p.to_string())).collect(),
    ))
}

pub fn explode(v: &Value) -> JResult<Value> {
    let s = as_str(v)?;
    Ok(Value::Array(
        s.chars()
            .map(|c| Value::Number(Number::from(c as u32)))
            .collect(),
    ))
}

pub fn implode(v: &Value) -> JResult<Value> {
    let arr = as_array(v)?;
    let mut s = String::new();
    for item in arr {
        if let Value::Number(n) = item {
            if let Some(c) = char::from_u32(num_f64(n) as u32) {
                s.push(c);
            }
        } else {
            return Err(JqError::msg("implode input must be an array of codepoints"));
        }
    }
    Ok(Value::String(s))
}

pub fn ascii_downcase(v: &Value) -> JResult<Value> {
    Ok(Value::String(as_str(v)?.to_ascii_lowercase()))
}

pub fn ascii_upcase(v: &Value) -> JResult<Value> {
    Ok(Value::String(as_str(v)?.to_ascii_uppercase()))
}

/// Writes `s` as a JSON string literal matching real jq's own
/// `jvp_dump_string` (`src/jv_print.c`) exactly: printable ASCII passes
/// through (escaping only `"`/`\`), the usual control-character
/// shorthands (`\b\t\r\n\f`) apply where they do, every other control
/// character (and DEL) becomes `\u00XX`, and non-ASCII passes through as
/// raw UTF-8 (jq's compact/`tostring` output is never ASCII-escaped,
/// unlike `-a`/`--ascii-output`, which only affects the CLI's own
/// printing, not any jq-language-level stringification).
fn write_jq_json_string(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        let code = c as u32;
        if (0x20..=0x7e).contains(&code) {
            if c == '"' || c == '\\' {
                out.push('\\');
            }
            out.push(c);
        } else if code < 0x20 || code == 0x7f {
            match c {
                '\u{8}' => out.push_str("\\b"),
                '\t' => out.push_str("\\t"),
                '\r' => out.push_str("\\r"),
                '\n' => out.push_str("\\n"),
                '\u{c}' => out.push_str("\\f"),
                _ => out.push_str(&format!("\\u{code:04x}")),
            }
        } else {
            out.push(c);
        }
    }
    out.push('"');
}

/// Writes `v` as compact JSON matching real jq's own serialization,
/// including the one place `serde_json`'s own `Display`/`to_string()`
/// disagrees with it: a scientific-notation exponent marker is always
/// uppercased (`"1E+20"`, not `"1e+20"` -- confirmed directly against
/// jq, not merely assumed). Object keys are written in the map's own
/// (insertion) order, same as real jq's default (unsorted) output.
fn write_jq_json(out: &mut String, v: &Value) {
    match v {
        Value::Null => out.push_str("null"),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Number(n) => {
            let s = n.to_string();
            if s.contains('e') {
                out.push_str(&s.replace('e', "E"));
            } else {
                out.push_str(&s);
            }
        }
        Value::String(s) => write_jq_json_string(out, s),
        Value::Array(items) => {
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i != 0 {
                    out.push(',');
                }
                write_jq_json(out, item);
            }
            out.push(']');
        }
        Value::Object(map) => {
            out.push('{');
            for (i, (k, v)) in map.iter().enumerate() {
                if i != 0 {
                    out.push(',');
                }
                write_jq_json_string(out, k);
                out.push(':');
                write_jq_json(out, v);
            }
            out.push('}');
        }
    }
}

pub fn value_to_display_string(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        other => {
            let mut out = String::new();
            write_jq_json(&mut out, other);
            out
        }
    }
}

pub fn to_string_value(v: &Value) -> Value {
    Value::String(value_to_display_string(v))
}

pub fn to_number_value(v: &Value) -> JResult<Value> {
    match v {
        Value::Number(_) => Ok(v.clone()),
        Value::String(s) => s
            .trim()
            .parse::<f64>()
            .ok()
            .map(|f| Value::Number(number_from_f64(f)))
            .ok_or_else(|| JqError::msg(format!("Cannot parse '{s}' as number"))),
        other => Err(JqError::msg(format!(
            "Cannot parse {} as number",
            type_name(other)
        ))),
    }
}

fn num_unary(v: &Value, f: impl Fn(f64) -> f64) -> JResult<Value> {
    match v {
        Value::Number(n) => Ok(Value::Number(number_from_f64(f(num_f64(n))))),
        other => Err(JqError::msg(format!(
            "{} is not a number",
            type_name(other)
        ))),
    }
}

pub fn floor_value(v: &Value) -> JResult<Value> {
    num_unary(v, f64::floor)
}

pub fn ceil_value(v: &Value) -> JResult<Value> {
    num_unary(v, f64::ceil)
}

pub fn round_value(v: &Value) -> JResult<Value> {
    num_unary(v, f64::round)
}

pub fn sqrt_value(v: &Value) -> JResult<Value> {
    num_unary(v, f64::sqrt)
}

pub fn fabs_value(v: &Value) -> JResult<Value> {
    num_unary(v, f64::abs)
}

/// Builds a jq object-construction entry; used by generated code for both
/// `{key: val}` and shorthand `{key}` / `{$var}` forms.
pub fn object_insert(
    mut m: Map<String, Value>,
    key: Value,
    val: Value,
) -> JResult<Map<String, Value>> {
    let k = match key {
        Value::String(s) => s,
        other => {
            return Err(JqError::msg(format!(
                "Object keys must be strings, got {}",
                type_name(&other)
            )))
        }
    };
    m.insert(k, val);
    Ok(m)
}
